const { chromium } = require("playwright");
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errs = [];
  page.on("console", (m) => { if (m.type() === "error") errs.push(m.text()); });
  page.on("pageerror", (e) => errs.push("PAGEERROR: " + e.message));
  await page.goto("http://127.0.0.1:3779/preview/mods", { waitUntil: "networkidle", timeout: 90000 });
  // scroll the flow section into view slowly
  await page.evaluate(async () => {
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    for (let y = 0; y <= 1600; y += 150) { window.scrollTo(0, y); await sleep(120); }
  });
  await page.waitForTimeout(1500);
  const info = await page.evaluate(() => {
    const hasIO = typeof IntersectionObserver !== "undefined";
    const op0 = document.querySelectorAll('[class*="opacity-0"]').length;
    const op100 = document.querySelectorAll('[class*="opacity-100"]').length;
    // find a flow card by text
    const flow = Array.from(document.querySelectorAll("h3")).find((h) => /honest steps|Upload it/.test(h.textContent || ""));
    const cardEl = flow ? flow.closest("div") : null;
    const cs = cardEl ? getComputedStyle(cardEl) : null;
    return {
      hasIO,
      opacity0Count: op0,
      opacity100Count: op100,
      firstCardOpacity: cs ? cs.opacity : "n/a",
      flowText: flow ? flow.textContent : "NOT FOUND",
    };
  });
  console.log(JSON.stringify(info, null, 2));
  console.log("CONSOLE ERRORS:", errs.slice(0, 8));
  await browser.close();
})();

